"""Versioned representation repairs; the sealed v2 contract remains unchanged.

Only an explicit coordinate declaration and the native host wait action gain
representations here. Neither operation repairs a model or establishes science.
"""
from __future__ import annotations

import copy
import json
import re

from . import commitment_v2 as previous
from .contracts import digest

VERSION = "ndfeb-terminal-commitment-v3"
CommitmentError = previous.CommitmentError
# These are declaration fields, not a search over arbitrary explanatory prose.
_FIELDS = {"requested_conditions": "requested_conditions", "indicated_conditions": "indicated_conditions"}
_CLAUSE = re.compile(
    r"All executable predictions (?:use |are (?:made|evaluated) at (?:the )?)"
    r"(requested|indicated) (?:setpoint|temperature_c|temperature) coordinates?(?=$|[;.])",
    re.IGNORECASE)
_ALIAS_FIELDS = {"candidate_temperature_c", "reference_temperature_c", "candidate_recipe", "reference_recipe"}
_MAPPING_FIELDS = {"requested_conditions_mapping", "indicated_conditions_mapping", "temperature_mapping", "coordinate_mapping"}
_INPUT_FIELDS = {"input", "input_coordinates", "coordinate_convention"}
_TYPED_COORDINATES = {
    "requested_conditions": "requested_conditions", "requested_temperature": "requested_conditions",
    "requested_temperature_c": "requested_conditions", "requested_setpoint": "requested_conditions",
    "indicated_conditions": "indicated_conditions", "indicated_temperature": "indicated_conditions",
    "indicated_temperature_c": "indicated_conditions", "indicated_setpoint": "indicated_conditions",
}
_MODEL_ALIASES = {"executable_model_id": "model_id", "executable_model_source_sha256": "source_sha256"}
_CONTRARY = re.compile(
    r"(?:predictions?|inputs?|model)\s+(?:actually\s+)?(?:use|uses|require|requires|evaluate|evaluates|are evaluated)"
    r"[^.;]{0,80}\b(requested|indicated)\b", re.IGNORECASE)
_NEGATION = re.compile(r"\b(?:do|does|must|will) not (?:use|evaluate)|\b(?:except|unless|only if)\b", re.IGNORECASE)


def _layers(parsed):
    i, *path = parsed["nomination_path"]
    obj = parsed["documents"][i]
    result = [obj]
    for key in path:
        obj = obj[key]
        if isinstance(obj, dict):
            result.append(obj)
    return result


def _reject_duplicate_alias_fields(raw):
    def pairs(items):
        found = {}
        for key, value in items:
            if key in {*_FIELDS, *_ALIAS_FIELDS, *_MAPPING_FIELDS, *_INPUT_FIELDS, *_MODEL_ALIASES} and key in found and found[key] != value:
                raise CommitmentError("conflicting duplicate coordinate alias field")
            found[key] = value
        return found
    decoder = json.JSONDecoder(object_pairs_hook=pairs)
    index = 0
    while index < len(raw):
        if raw[index] != "{":
            index += 1
            continue
        try:
            _, length = decoder.raw_decode(raw[index:])
        except json.JSONDecodeError:
            index += 1
            continue
        index += length


def _typed_input(value):
    if isinstance(value, str):
        return _TYPED_COORDINATES.get(value)
    if not isinstance(value, dict):
        return None
    values = [value[key] for key in _INPUT_FIELDS if key in value]
    normalized = [_TYPED_COORDINATES.get(v) if isinstance(v, str) else None for v in values]
    if normalized and len(set(normalized)) > 1:
        raise CommitmentError("conflicting typed input coordinate declarations")
    return normalized[0] if normalized else None


def _structured_mappings(parsed):
    for layer in _layers(parsed):
        for field in sorted(_MAPPING_FIELDS):
            if isinstance(layer.get(field), dict):
                yield field, layer[field]


def _alias(parsed, canonical):
    declarations = []
    for layer in _layers(parsed):
        for field, expected in _FIELDS.items():
            if field not in layer:
                continue
            value = layer[field]
            if not isinstance(value, str):
                continue
            match = _CLAUSE.match(value.strip())
            if match is None:
                continue
            coordinate = match[1].lower() + "_conditions"
            if coordinate != expected:
                raise CommitmentError("coordinate declaration field contradicts its explicit clause")
            tail = value.strip()[match.end():]
            if _NEGATION.search(tail) or any(
                m[1].lower() + "_conditions" != coordinate for m in _CONTRARY.finditer(tail)
            ):
                raise CommitmentError("conditional or contradictory coordinate declaration")
            declarations.append({"field": field, "input": coordinate, "raw": value})
    for field, value in _structured_mappings(parsed):
        coordinate = _typed_input(value)
        if coordinate is None:
            continue
        if field in {"requested_conditions_mapping", "indicated_conditions_mapping"} and coordinate != field.removesuffix("_mapping"):
            raise CommitmentError("typed coordinate mapping field contradicts its input declaration")
        declarations.append({"field": field, "input": coordinate, "raw": copy.deepcopy(value)})
    canonical_input = canonical["input"] or _typed_input(canonical["raw"])
    if canonical["input"] is None and canonical_input is not None:
        declarations.append({"field": "prediction_coordinates", "input": canonical_input,
                             "raw": copy.deepcopy(canonical["raw"])})
    values = {item["input"] for item in declarations}
    if len(values) > 1:
        raise CommitmentError("conflicting coordinate alias declarations")
    if not declarations:
        return None
    value = declarations[0]["input"]
    if canonical["raw"] is not None and canonical_input != value:
        raise CommitmentError("coordinate alias conflicts with canonical declaration")
    return {"input": value, "status": "explicit_coordinate_representation", "raw": declarations,
            "grammar": "finite affirmative coordinate clauses or typed input-coordinate aliases",
            "scientific_mapping_verified": False}


def _recipe_alias_projection(parsed):
    raw = copy.deepcopy(parsed["nomination"])
    aliases = []
    for field, value in _structured_mappings(parsed):
        for alias, canonical_key in _MODEL_ALIASES.items():
            if alias not in value:
                continue
            if canonical_key in raw and raw[canonical_key] != value[alias]:
                raise CommitmentError("coordinate mapping conflicts with " + canonical_key)
            raw[canonical_key] = value[alias]
            aliases.append(field + "." + alias)
    for role in ("candidate", "reference"):
        temp_key, recipe_key = role + "_temperature_c", role + "_recipe"
        for key in (temp_key, recipe_key):
            values = [layer[key] for layer in _layers(parsed) if key in layer]
            if values and any(value != values[0] for value in values[1:]):
                raise CommitmentError("conflicting enclosing " + key)
        representations = []
        if raw.get(role) is not None:
            representations.append(raw[role])
        if recipe_key in raw:
            recipe = copy.deepcopy(raw[recipe_key])
            if not isinstance(recipe, dict):
                raise CommitmentError(recipe_key + " requires an explicit recipe object")
            for key in ("origin", "lot_id"):
                if key in recipe and recipe.pop(key) != previous.DEFAULT_MISSION[key]:
                    raise CommitmentError(recipe_key + " changes mission " + key)
            representations.append(recipe)
            aliases.append(recipe_key)
        if raw.get(temp_key) is not None:
            representations.append({"temperature_c": raw[temp_key]})
            aliases.append(temp_key)
        if representations:
            normalized = [previous._recipe(obj, role, previous.DEFAULT_MISSION) for obj in representations]
            if any(value != normalized[0] for value in normalized[1:]):
                raise CommitmentError("conflicting " + role + " temperature/recipe declarations")
            if role == "candidate" and raw["recommendation_status"] != "recommend_candidate":
                raise CommitmentError("withhold/retain_reference must not also nominate a candidate")
            raw[role] = normalized[0]
    if not aliases:
        return None
    raw["scope"] = parsed["scope"]
    return raw, aliases


def normalize_commitment(rationale, *, terminal, registered_models, prior_evidence, mission=None):
    original = copy.deepcopy(terminal)
    if not isinstance(rationale, str) or rationale != original.get("rationale"):
        raise CommitmentError("rationale differs from the original terminal event")
    _reject_duplicate_alias_fields(rationale)
    binding = {"terminal": original, "registered_models": registered_models,
               "prior_evidence": prior_evidence, "mission": mission}
    if original.get("decision") == "wait":
        # Native wait means no intervention is currently committed. It does not
        # mean permanent refusal or proven structural unavailability. Conflicting
        # explicit decisions still cannot masquerade as a wait action.
        explicit = None
        try:
            explicit = previous.parse_commitment(rationale)
        except CommitmentError as exc:
            if str(exc) != "expected exactly one explicit final recommendation object":
                raise
            if '"recommendation_status"' in rationale:
                raise CommitmentError("ambiguous explicit recommendation in host wait") from exc
        else:
            explicit_projection = _recipe_alias_projection(explicit)
            if explicit_projection:
                explicit["nomination"] = explicit_projection[0]
            if explicit["nomination"]["recommendation_status"] != "withhold" or explicit["nomination"].get("candidate") is not None:
                raise CommitmentError("host wait conflicts with explicit candidate or retention")
        projection = {"recommendation_status": "withhold", "candidate": None,
                      "scope": rationale, "evidence_ids": []}
        projected = {**original, "decision": "stop", "rationale": json.dumps(explicit["nomination"] if explicit else projection, sort_keys=True)}
        result = previous.normalize_commitment(projected["rationale"], **{**binding, "terminal": projected})
        prior_projection = copy.deepcopy(result)
        result["terminal_sha256"] = digest(original)
        result["normalization"] = {"raw_rationale": rationale, "host_action": "wait",
                                   "projected_v2_normalization": result["normalization"]}
        result["action_projection"] = {
            "kind": "host_wait_to_current_window_withhold", "host_terminal": original,
            "projected_terminal_sha256": digest(projected), "continuation": "awaiting_operator",
            "structural_unavailability_asserted": False,
            "policy_citations_inferred": False, "candidate_inferred": False,
            "explicit_policy_withhold": explicit is not None,
        }
    else:
        parsed = previous.parse_commitment(rationale)
        projection = _recipe_alias_projection(parsed)
        if projection:
            raw, fields = projection
            projected = {**original, "rationale": json.dumps(raw, sort_keys=True)}
            result = previous.normalize_commitment(projected["rationale"], **{**binding, "terminal": projected})
            prior_projection = copy.deepcopy(result)
            result["terminal_sha256"] = digest(original)
            result["normalization"] = parsed
            result["recipe_representation_projection"] = {"fields": fields,
                "projected_terminal_sha256": digest(projected), "original_terminal_sha256": digest(original),
                "fixed_recipe_changes_allowed": False}
        else:
            result = previous.normalize_commitment(rationale, **binding)
            prior_projection = copy.deepcopy(result)
        alias = _alias(result["normalization"], result["coordinate_declaration"])
        if alias:
            result["prediction_coordinates"] = alias["input"]
            result["coordinate_declaration"] = alias
            result["validity"]["prediction_input_coordinates_declared"] = True
    result["schema"] = VERSION
    result["representation_revision"] = {"previous_schema": previous.VERSION,
                                          "previous_projection_sha256": digest(prior_projection),
                                          "scientific_model_changed": False}
    return result


def validate_commitment(commitment, *, terminal, registered_models, prior_evidence, mission=None):
    if not isinstance(commitment, dict) or commitment.get("schema") != VERSION:
        raise CommitmentError("expected a normalized v3 commitment")
    expected = normalize_commitment(commitment.get("normalization", {}).get("raw_rationale"),
                                   terminal=terminal, registered_models=registered_models,
                                   prior_evidence=prior_evidence, mission=mission)
    if expected != commitment:
        raise CommitmentError("normalized commitment differs from authenticated inputs")
    return copy.deepcopy(commitment)
